# Source for q/ae-views-stress.js: Stress echo + Echo views/maneuvers + Measurements (hemodynamic calculations).
S="Stress echo"; V="Echo views"; M="Measurements"
Q=[
# --- Stress echo: protocols ---
(S,"Age-predicted maximum heart rate is commonly estimated as:","220 − age",["200 − age","180 + age","Resting HR × 2"],"The target for an adequate test is usually 85% of this value.","F"),
(S,"The Bruce treadmill protocol increases:","Both speed and incline every 3 minutes",["Only speed every minute","Only incline every 10 minutes","Nothing; it is constant"],"Stages continue until symptoms, target endpoints or exhaustion.","F"),
(S,"In a dobutamine stress echo, if the target heart rate is not reached at the highest dobutamine dose, the usual next step is to:","Add atropine",["Stop and report a normal test","Give a beta-blocker","Give adenosine"],"Atropine raises heart rate and improves sensitivity.","F"),
(S,"Typical dobutamine stages in DSE are:","About 3-minute stages rising from about 5 or 10 up to 40 mcg/kg/min",["One large bolus","30-minute stages","Doses in mg/kg/hour only"],"Images are taken at rest, low dose, peak and recovery.","F"),
(S,"A standard stress echo display usually shows:","Rest, low-dose (or mid), peak and recovery images side by side for each view",["Only peak images","Only M-mode","Only Doppler"],"Side-by-side quad screens make new wall motion changes easier to see.","F"),
(S,"The standard views for wall motion in stress echo are:","PLAX, PSAX, apical 4-chamber and apical 2-chamber (often apical long-axis too)",["Subcostal and suprasternal only","PLAX only","A4C only"],"Together they show all 17 segments.","F"),
(S,"Contrast should be used in stress echo when:","Two or more contiguous segments are not well seen",["Images are excellent","The patient is young","Only for treadmill tests"],"Contrast improves reader confidence and accuracy.","F"),
(S,"Dipyridamole or adenosine stress works mainly by:","Dilating coronary arteries, causing flow differences between normal and narrowed vessels",["Raising heart rate strongly","Increasing contractility directly","Blocking beta receptors"],"Aminophylline can reverse the effects of dipyridamole and adenosine.","C"),
(S,"Which is a contraindication to dobutamine stress echo?","Uncontrolled severe hypertension",["Controlled hypertension","Mild MR","Prior CABG"],"Other contraindications include unstable arrhythmia and acute aortic dissection.","F"),
(S,"Which of these is a reason to stop a dobutamine stress test?","A drop in systolic blood pressure with a new wall motion abnormality",["Reaching 50% of target HR","Mild palpitations only","A normal response"],"Other endpoints include serious arrhythmias, severe symptoms and target HR.","F"),
# --- Stress echo: interpretation ---
(S,"With ischemia during stress, the LV cavity often:","Dilates, and the EF falls",["Gets much smaller","Stays exactly the same in all cases","Becomes hypertrophied"],"A normal LV gets smaller and more hyperdynamic with stress.","F"),
(S,"Ischemic LV cavity dilation during stress suggests:","Severe or multivessel coronary disease",["A normal test","Mild single-vessel disease only","Pericarditis"],"It is a high-risk finding.","F"),
(S,"A fall in blood pressure during exercise suggests:","Severe ischemia such as left main or three-vessel disease",["A normal response","Low anxiety","Good fitness"],"Blood pressure normally rises with exercise.","F"),
(S,"Which can cause a false-negative stress echo?","Not reaching the target heart rate or waiting too long to image after exercise",["Excellent image quality","Reaching 95% target HR","Imaging within 60 seconds"],"Beta-blockers can also blunt the heart rate response.","F"),
(S,"Which can cause a false-positive stress echo?","LBBB septal motion or a hypertensive response",["Normal wall motion","Normal ECG","Adequate heart rate"],"The basal inferior wall can also look falsely abnormal.","C"),
(S,"A segment that is akinetic at rest and stays akinetic at all stress levels suggests:","Scar (nonviable myocardium)",["Ischemia only","Normal myocardium","Hibernation"],"Viable segments improve at low dose.","F"),
(S,"Typical sensitivity and specificity of stress echo for coronary disease is about:","80–85% for both",["50% for both","99% for both","Sensitivity 20%, specificity 95%"],"Accuracy depends on image quality and reader experience.","C"),
(S,"An exercise ECG response usually considered positive for ischemia is:","At least 1 mm horizontal or downsloping ST depression",["Upsloping ST depression of 0.5 mm","A shorter PR interval","A taller P wave"],"Stress echo adds wall motion information to the ECG.","C"),
# --- Stress echo: valves and diastology ---
(S,"Low-dose dobutamine in low-flow, low-gradient AS with low EF is used mainly to:","Tell true severe AS from pseudo-severe AS and check contractile reserve",["Measure LV mass","Test for coronary spasm","Measure the aorta"],"Doses usually go up to about 20 mcg/kg/min.","F"),
(S,"In low-flow, low-gradient AS on dobutamine, true severe AS is suggested when:","The mean gradient rises to at least 40 mmHg while the valve area stays at or under 1.0 cm²",["Valve area rises well above 1.0 cm²","The gradient stays low and area rises","The heart rate falls"],"In pseudo-severe AS, the valve opens more as flow increases.","C"),
(S,"Contractile (flow) reserve on dobutamine stress is usually defined as:","An increase in stroke volume of at least 20%",["Any increase in heart rate","A drop in EF","An increase in MR"],"Patients without reserve have a higher surgical risk.","C"),
(S,"In mitral stenosis, exercise stress echo is helpful when symptoms do not match the resting severity. A significant response is:","Mean gradient over about 15 mmHg or PASP over about 60 mmHg with exercise",["Mean gradient under 5 mmHg","No change in PASP","Lower heart rate"],"These findings may support intervention.","C"),
(S,"A diastolic stress test is considered abnormal when, with exercise:","Average E/e′ is over 14 and TR velocity is over 2.8 m/s",["E/e′ falls under 8","TR velocity falls","Heart rate rises"],"It helps diagnose HFpEF in patients with exercise symptoms.","C"),
(S,"In HCM, exercise stress echo is used to:","Bring out a hidden LVOT gradient of 50 mmHg or more",["Measure the ejection fraction only","Measure the aortic annulus","Close a PFO"],"Exercise is preferred to dobutamine for this purpose.","F"),
(S,"In secondary (functional) MR, exercise echo is significant if:","EROA increases by about 0.13 cm² or more",["EROA falls","MR disappears","LV size decreases"],"Dynamic MR worsening is linked with poorer outcomes.","C"),
# --- Views and maneuvers ---
(V,"The Valsalva strain phase:","Reduces venous return (preload)",["Increases preload","Increases afterload greatly","Has no effect on the heart"],"Strain lowers preload; release brings a rush of venous return.","F"),
(V,"During Valsalva strain, a pseudonormal mitral inflow pattern usually:","Changes to impaired relaxation with E/A falling by 50% or more",["Becomes restrictive","Does not change","Shows E/A over 3"],"Lower preload unmasks the underlying relaxation problem.","C"),
(V,"Which maneuver increases the LVOT gradient in obstructive HCM?","Valsalva strain or standing",["Squatting","Handgrip","Leg raising"],"Lower preload or afterload makes the LV smaller and worsens obstruction.","F"),
(V,"Handgrip exercise increases afterload, which:","Lowers the HCM gradient and makes MR louder",["Raises the HCM gradient","Has no effect","Makes MR disappear"],"It is sometimes used at the bedside to tell murmurs apart.","C"),
(V,"Amyl nitrite inhalation affects the HCM gradient by:","Lowering afterload and increasing the gradient",["Raising afterload and decreasing the gradient","No effect","Making the LV larger"],"It is a provocative test for dynamic obstruction.","C"),
(V,"Passive leg raising increases:","Preload (venous return)",["Afterload only","Heart rate","LVOT gradient in HCM"],"It can test fluid responsiveness using LVOT VTI changes.","F"),
(V,"Right-sided heart flow velocities and murmurs typically increase with:","Inspiration",["Expiration","Valsalva strain","Standing"],"More venous return reaches the right heart with inspiration.","F"),
(V,"For an agitated saline study to find a PFO, bubbles are best given with:","A release of Valsalva, which briefly raises RA pressure above LA pressure",["Deep inhalation only","The patient holding still","Handgrip"],"Bubbles in the left heart within about 3 to 5 beats suggest a PFO.","F"),
(V,"An LV that is foreshortened in the apical view can be corrected by:","Moving the transducer more lateral and lower, often one rib space down",["Increasing depth only","Using higher gain","Moving to the subcostal view only"],"The true apex is the thin, rounded tip that does not move much.","F"),
(V,"Stitching artifact in 3D full-volume imaging is caused by:","Patient or heart movement between beats used to build the volume",["Low gain","Too much contrast","A low-frequency transducer"],"Use breath-hold and regular rhythm, or single-beat 3D.","F"),
(V,"The mid-esophageal two-chamber TEE view is usually obtained at about:","80° to 100°",["0°","30°","130°"],"It shows the LA, LAA and LV anterior and inferior walls.","C"),
(V,"The mid-esophageal mitral commissural TEE view at about 60° shows:","Both commissures, with P3, A2 and P1 scallops",["The aortic valve in short axis","The bicaval view","The pulmonic valve only"],"It helps locate mitral valve pathology.","C"),
(V,"Which TEE view gives the best Doppler alignment with the aortic valve?","Deep transgastric long axis",["Mid-esophageal four-chamber","Upper esophageal aortic arch","Mid-esophageal bicaval"],"Transgastric long-axis views are another option.","C"),
(V,"Turning the TEE probe to the left from mid-esophageal level, then pulling back, follows the:","Descending thoracic aorta to the arch",["Mitral valve","Pulmonic valve","RA"],"The aorta is seen in short axis at 0° and long axis at 90°.","C"),
(V,"The right parasternal view for AS Doppler is best done with the patient:","In the right lateral decubitus position",["In the left lateral position","Standing","Prone"],"Use a dedicated CW (pencil) probe.","F"),
(V,"Which view is preferred to look for a pericardial effusion and guide pericardiocentesis in many patients?","Subcostal",["Suprasternal","PLAX only","Right parasternal"],"The apical approach is another option depending on where the fluid collects.","F"),
(V,"In the PLAX view, a pericardial effusion is told apart from a pleural effusion because a pericardial effusion lies:","Anterior to the descending aorta",["Posterior to the descending aorta","Only around the RV","Behind the LA only"],"Left pleural fluid extends posterior to the descending aorta.","F"),
(V,"An off-axis apical image showing the LVOT and aortic valve is called the:","Apical five-chamber view",["Apical two-chamber view","Subcostal view","PLAX"],"It is used for LVOT and AV Doppler.","F"),
(V,"In the suprasternal notch view, which vessels branch from the aortic arch?","Brachiocephalic, left common carotid and left subclavian arteries",["Coronary arteries","Pulmonary veins","Renal arteries"],"The right pulmonary artery is seen beneath the arch in cross section.","F"),
# --- Measurements: calculations ---
(M,"The aortic root at the sinuses of Valsalva is measured by ASE convention:","At end-diastole, leading edge to leading edge",["At end-systole, inner edge to inner edge","Only on M-mode","At the annulus"],"The annulus is measured in mid-systole, inner edge to inner edge.","C"),
(M,"Qp/Qs is calculated as:","Pulmonic stroke volume ÷ systemic stroke volume",["Systemic ÷ pulmonic","LVOT VTI × heart rate","EF ÷ LV mass"],"Qp/Qs over 1.5 suggests a significant left-to-right shunt.","F"),
(M,"RVOT diameter 2.5 cm, RVOT VTI 20 cm, LVOT diameter 2.0 cm, LVOT VTI 20 cm. Qp/Qs is about:","1.56",["1.0","1.25","2.5"],"Equal VTIs mean the ratio equals (2.5 ÷ 2.0)² = 1.5625.","C"),
(M,"LV dP/dt from the MR CW jet uses the time for velocity to rise from:","1 m/s to 3 m/s",["0 to 1 m/s","3 m/s to 5 m/s","1 m/s to 2 m/s"],"The pressure change between these points is 32 mmHg.","C"),
(M,"The MR jet takes 32 ms to rise from 1 to 3 m/s. dP/dt is:","1,000 mmHg/s",["32 mmHg/s","3,200 mmHg/s","100 mmHg/s"],"32 mmHg ÷ 0.032 s = 1,000 mmHg/s, which is reduced (normal over 1,200).","C"),
(M,"The myocardial performance (Tei) index is calculated as:","(Isovolumic contraction time + isovolumic relaxation time) ÷ ejection time",["Ejection time ÷ IVRT","E ÷ A","EF × heart rate"],"A higher value means worse combined systolic and diastolic function.","C"),
(M,"Systolic BP 110 mmHg and MR peak velocity 5 m/s. Estimated LA systolic pressure is:","10 mmHg",["100 mmHg","35 mmHg","0 mmHg"],"LAP = SBP − 4V² = 110 − 100 = 10 mmHg (assuming no LVOT obstruction or AS).","C"),
(M,"Diastolic BP 70 mmHg and AR end-diastolic velocity 4 m/s. Estimated LVEDP is:","6 mmHg",["64 mmHg","16 mmHg","70 mmHg"],"LVEDP = DBP − 4V² = 70 − 64 = 6 mmHg.","C"),
(M,"Systolic BP 120 mmHg and a VSD jet of 4.5 m/s. Estimated RV systolic pressure is:","39 mmHg",["81 mmHg","120 mmHg","20 mmHg"],"RVSP = SBP − 4V² = 120 − 81 = 39 mmHg.","C"),
(M,"Mean PA pressure can be estimated from the PR jet using:","The early diastolic peak velocity: 4V² + RA pressure",["The end-diastolic velocity only","The TR jet only","The LVOT VTI"],"The PR end-diastolic velocity gives PA diastolic pressure.","C"),
(M,"An RVOT acceleration time under about 100 ms suggests:","Pulmonary hypertension",["Normal PA pressure","Pulmonic stenosis only","Aortic stenosis"],"A mid-systolic notch in the RVOT signal also suggests raised PVR.","F"),
(M,"Peak velocity of 4 m/s across the aortic valve gives a peak gradient of:","64 mmHg",["16 mmHg","40 mmHg","32 mmHg"],"4 × 4² = 64 mmHg.","F"),
(M,"Cardiac index is calculated as:","Cardiac output ÷ body surface area",["Stroke volume × BSA","EF ÷ BSA","Heart rate ÷ BSA"],"A normal resting cardiac index is about 2.5 to 4.0 L/min/m².","F"),
(M,"Stroke volume 70 mL, heart rate 80 bpm and BSA 2.0 m². What is the cardiac index?","2.8 L/min/m²",["5.6 L/min/m²","1.4 L/min/m²","35 L/min/m²"],"CO = 0.07 × 80 = 5.6 L/min. 5.6 ÷ 2.0 = 2.8.","C"),
(M,"In the 2016 ASE diastolic guideline, the four main variables for patients with normal EF are:","Average E/e′ over 14, septal e′ under 7 or lateral e′ under 10, TR velocity over 2.8 m/s, LAVI over 34 mL/m²",["EF, LV mass, TAPSE, IVC","Aortic velocity, LVOT VTI, MR and AR","QRS width, heart rate, blood pressure and BSA"],"Diastolic dysfunction is present if more than half are abnormal.","C"),
(M,"The ascending aorta is usually measured:","About 1 cm above the sinotubular junction or at the widest point, in the PLAX view",["In the apical four-chamber view","In the subcostal view only","At the LVOT"],"Moving the transducer up one interspace often shows more of the ascending aorta.","F"),
(M,"Why is the Teichholz formula no longer recommended for LV volumes?","It assumes a uniform shape and is inaccurate with regional wall motion abnormalities",["It is too accurate","It needs 3D imaging","It uses Doppler"],"Use the biplane method of disks or 3D instead.","F"),
(M,"Peak instantaneous Doppler gradient in AS is usually higher than the peak-to-peak catheter gradient because:","The two peaks happen at different times; they are not the same measurement",["Doppler is always wrong","The catheter measures velocity","They should be identical"],"Mean gradients match better between Doppler and catheter.","C"),
(M,"In coarctation, the expanded Bernoulli equation should be used when:","The velocity before the narrowing is over about 1.5 m/s",["The jet is under 1 m/s","The patient is in AF","Always ignored"],"4(V2² − V1²) avoids overestimating the gradient.","C"),
(M,"A diastolic 'tail' (continuous flow) on the coarctation CW Doppler signal suggests:","A severe coarctation",["Mild coarctation","Normal aorta","Aortic regurgitation only"],"Pressure stays raised across the narrowing through diastole.","F"),
(M,"Peak TR velocity 2.5 m/s and RA pressure 15 mmHg. The estimated RVSP is:","40 mmHg",["25 mmHg","55 mmHg","10 mmHg"],"4 × 2.5² = 25, plus 15 = 40 mmHg.","F"),
(M,"A dilated IVC (over 2.1 cm) that collapses less than 50% with sniff suggests RA pressure of about:","15 mmHg",["3 mmHg","0 mmHg","30 mmHg"],"Intermediate findings give about 8 mmHg.","F"),
(M,"The TR velocity ÷ RVOT VTI ratio is used to estimate:","Pulmonary vascular resistance",["Aortic valve area","LV mass","LA volume"],"A ratio over about 0.2 suggests raised PVR (over 2 Wood units).","C"),
(M,"The mitral annulus diameter for mitral inflow stroke volume is measured in the:","Apical four-chamber (and two-chamber) view in early to mid diastole",["PLAX in systole","Subcostal view","Suprasternal view"],"The annulus is often assumed circular, which adds error.","C"),
(M,"Reporting LV size by 3D echo is preferred when available because 3D:","Does not depend on geometric assumptions or foreshortening",["Is always faster","Needs no training","Works with any image quality"],"3D volumes are closer to cardiac MRI values.","F"),
]
